use vstd::prelude::*;

verus! {
    fn append_array(a: &[i32], b: &[i32]) -> (c: Vec<i32>)
        requires
            a.len() + b.len() <= u32::MAX as usize, // Ensure the total length does not exceed the maximum
        ensures
            c.len() == a.len() + b.len(),
            forall(|i: nat| (i < a.len() as nat) ==> c[i] == a[i]),
            forall(|j: nat| (j < b.len() as nat) ==> c[(a.len() as nat) + j] == b[j]),
    {
        let mut c: Vec<i32> = Vec::with_capacity(a.len() + b.len());
        
        // Append elements from the first array
        let mut i: usize = 0;
        while i < a.len()
            invariant
                i <= a.len(),
                c.len() == i,
                forall(|k: nat| (k < i as nat) ==> c[k] == a[k]),
            decreases a.len() - i,
        {
            c.push(a[i]);
            i = i + 1;
        }

        // Append elements from the second array
        let mut j: usize = 0;
        while j < b.len()
            invariant
                j <= b.len(),
                c.len() == (a.len() + j),
                forall(|k: nat| (k < j as nat) ==> c[(a.len() as nat) + k] == b[k]),
            decreases b.len() - j,
        {
            c.push(b[j]);
            j = j + 1;
        }

        c
    }
}
